21: export async function send(db, text, values = {}) {
22:   return db.query(text, values);
23: }

135: export async function removeVoid(db, invoiceId) {
136:   const result = await send(db, "DELETE FROM invoices WHERE id=:invoiceId AND status='void'", {invoiceId});
137:   return { removed: result.changes };
138: }

7: export function chosenOrder(value) {
8:   const choices = Object.freeze({
9:     recent: 'created_at DESC',
10:     amount: 'total_cents DESC',
11:     name: 'customer_id ASC'
12:   });
13:   return Object.hasOwn(choices, value) ? choices[value] : choices.recent;
14: }

124: export async function paymentFeed(db, input) {
125:   const order = chosenOrder(input.order);
126:   const rows = await db.query('SELECT id,total_cents,created_at FROM invoices ORDER BY ' + order + ' LIMIT :limit', {limit:25});
127:   return rows.map(row => ({...row, dollars:row.total_cents / 100}));
128: }

18: export function regionScope(value) {
19:   return value ? "region = '" + value + "'" : '1 = 1';
20: }

129: export async function revenueSummary(db, request) {
130:   const region = normaliseRegion(request.region);
131:   const scope = regionScope(region);
132:   const rows = await db.query('SELECT region,COUNT(*) count,SUM(total_cents) cents FROM invoices WHERE created_at>=:from AND created_at<:to AND ' + scope + ' GROUP BY region', {from:request.from,to:request.to});
133:   return rows.map(row => ({...row, dollars:row.cents / 100}));
134: }
